import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class SecureCode {
    public static void main(String[] args) {
        String dbUrl = "jdbc:mysql://localhost:3306/mydb";
        String dbUser = "myuser";
        String dbPassword = "mypassword";

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {
            String query = "SELECT * FROM users WHERE username = ?";

            try (PreparedStatement pstmt = conn.prepareStatement(query)) {
                pstmt.setString(1, args[0]); // Set the parameter value securely

                ResultSet rs = pstmt.executeQuery();

                while (rs.next()) {
                    System.out.println(rs.getString("username"));
                }
            }
        } catch (SQLException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
```

In the vulnerable code snippet, the `username` parameter is directly concatenated into the SQL query string. This makes the code vulnerable to SQL injection attacks, where an attacker could inject malicious SQL code by providing a specially crafted `username` argument.

In the secure code snippet, the `username` parameter is set as a parameter in the SQL query using a `PreparedStatement`. This ensures that the parameter value is treated as a literal value, rather than part of the SQL code, making the code secure against SQL injection attacks.

